get_seo_configuration_document_root.code:
final response = await client.seoConfiguration
    .getSeoConfigurationDocumentRoot(queryParams: {'limit': 100});
final files = (response.map as Map)['items'] as List;
for (final file in files) {
  print('${(file as Map)['config_key']} ${file['file_name']}');
}

upload_seo_configuration_document_root.code:
import 'dart:io';

final contents = await File('verification.txt').readAsBytes();
final response =
    await client.seoConfiguration.uploadSeoConfigurationDocumentRoot({
  'file': ['verification.txt', contents, 'text/plain'],
});
final documentRootFile = (response.map as Map)['document_root_file'] as Map;
print(documentRootFile['config_key']);

get_seo_configuration_redirects.code:
